# The client status replaces New / Existing (plan.md §5.1, §6.2; slice 6). deals sits left of quotes and its migrations
# never depend on quotes (§3.3), so this one maps what deals alone can see: new → prospect and existing →
# existing_client. quotes' 0002_client_status_from_sales, which depends on this one, then turns an existing client with
# a sold plan into a new_client converted by the sale (2V flipped a client to existing when a plan sold).


def statuses(apps, schema_editor):
    Client = apps.get_model('deals', 'Client')
    Deal = apps.get_model('deals', 'Deal')
    Client.objects.filter(relationship='new').update(relationship='prospect')
    Client.objects.filter(relationship='existing').update(relationship='existing_client')
    # A deal opened as its client's status (it follows the status until a sale; quotes' migration fixes sold deals).
    for status in ('prospect', 'new_client', 'existing_client'):
        Deal.objects.filter(client__relationship=status).update(opened_as=status)


